import{_ as e,o as t,c as n,a0 as i}from"./chunks/framework.Bmhw_dvp.js";const k=JSON.parse('{"title":"Danmaku System","description":"","frontmatter":{},"headers":[],"relativePath":"en/features/danmaku.md","filePath":"en/features/danmaku.md","lastUpdated":1786689844000}'),r={name:"en/features/danmaku.md"};function o(d,a,u,s,l,m){return t(),n("div",null,[...a[0]||(a[0]=[i('<h1 id="danmaku-system" tabindex="-1">Danmaku System <a class="header-anchor" href="#danmaku-system" aria-label="Permalink to &quot;Danmaku System&quot;">​</a></h1><h2 id="feature-overview" tabindex="-1">Feature Overview <a class="header-anchor" href="#feature-overview" aria-label="Permalink to &quot;Feature Overview&quot;">​</a></h2><p>Danmaku are scrolling text comments that float across the video画面. ZViewer supports multiple danmaku sources, letting you enjoy a lively atmosphere while watching anime and movies.</p><hr><h2 id="multi-track-danmaku-aggregation" tabindex="-1">Multi-track Danmaku Aggregation <a class="header-anchor" href="#multi-track-danmaku-aggregation" aria-label="Permalink to &quot;Multi-track Danmaku Aggregation&quot;">​</a></h2><p>ZViewer supports loading danmaku from multiple video sources simultaneously and displaying them in layers. For example, the same anime on Bilibili may have several personal upload versions, each with its own independent danmaku set. With the multi-track aggregation feature, you can overlay danmaku from multiple video sources together, effectively doubling the danmaku density and making the viewing experience more lively.</p><h2 id="three-danmaku-sources" tabindex="-1">Three Danmaku Sources <a class="header-anchor" href="#three-danmaku-sources" aria-label="Permalink to &quot;Three Danmaku Sources&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Source</th><th>Description</th></tr></thead><tbody><tr><td>Bilibili Official Danmaku</td><td>Danmaku pulled from the original Bilibili video</td></tr><tr><td>DandanPlay Danmaku</td><td>Third-party danmaku library aggregating multiple sources</td></tr><tr><td>Custom Danmaku</td><td>Real-time danmaku sent by you and your friends in the room</td></tr></tbody></table><h2 id="loading-bilibili-danmaku" tabindex="-1">Loading Bilibili Danmaku <a class="header-anchor" href="#loading-bilibili-danmaku" aria-label="Permalink to &quot;Loading Bilibili Danmaku&quot;">​</a></h2><p>After adding a Bilibili video, danmaku loads automatically and scrolls from right to left across the video画面.</p><h2 id="sending-custom-danmaku" tabindex="-1">Sending Custom Danmaku <a class="header-anchor" href="#sending-custom-danmaku" aria-label="Permalink to &quot;Sending Custom Danmaku&quot;">​</a></h2><p>In the <strong>&quot;Live Danmaku&quot; tab</strong> on the right panel, type your message and send it. All viewers can see it.</p><h2 id="danmaku-track-management" tabindex="-1">Danmaku Track Management <a class="header-anchor" href="#danmaku-track-management" aria-label="Permalink to &quot;Danmaku Track Management&quot;">​</a></h2><p>In the <strong>&quot;Danmaku Tracks&quot; tab</strong>, you can block keywords, adjust danmaku style (font / color / opacity / speed), and disable individual danmaku tracks.</p><h2 id="frequently-asked-questions" tabindex="-1">Frequently Asked Questions <a class="header-anchor" href="#frequently-asked-questions" aria-label="Permalink to &quot;Frequently Asked Questions&quot;">​</a></h2><h3 id="danmaku-not-showing" tabindex="-1">Danmaku not showing? <a class="header-anchor" href="#danmaku-not-showing" aria-label="Permalink to &quot;Danmaku not showing?&quot;">​</a></h3><p>Make sure the video is loaded, check whether the danmaku track has been loaded, and try re-adding the video.</p>',17)])])}const c=e(r,[["render",o]]);export{k as __pageData,c as default};
